            row.append((r0, r1, c0, c1, colors))
        cell_color.append(row)
    nr, nc = len(cell_color), len(cell_color[0])
    painted = [[set() for _ in range(nc)] for _ in range(nr)]
    markers = {}
    for i in range(nr):
        for j in range(nc):
            for color in cell_color[i][j][4]:
                markers.setdefault(color, []).append((i, j))
    for color, points in markers.items():
        # Join marker pairs lying in the same tile row or column.
        for a in range(len(points)):
            r1, c1 = points[a]
            for b in range(a + 1, len(points)):
                r2, c2 = points[b]
                if r1 == r2:
                    for c in range(min(c1, c2), max(c1, c2) + 1):
                        painted[r1][c].add(color)
                elif c1 == c2:
                    for r in range(min(r1, r2), max(r1, r2) + 1):
                        painted[r][c1].add(color)
    out = [list(row) for row in grid]
    for i in range(nr):
        for j in range(nc):
            colors = painted[i][j]
            if not colors:
